/**
 * Swept AABB (continuous) collision detection for one fixed timestep.
 *
 * Time `t` is normalized to [0, 1] over the step (e.g. 1/60 s), so a
 * velocity of 300 px/frame moves the box 300 * t pixels by time t.
 *
 * Algorithm: slab method on the Minkowski-reduced problem. Per axis we
 * compute when the moving box's leading edge enters the wall's slab and
 * when its trailing edge exits it. The boxes touch/overlap exactly during
 * the interval [tEnter, tExit] where tEnter = max(axis entries) and
 * tExit = min(axis exits). A hit exists iff tEnter <= tExit, the interval
 * intersects [0, 1], and the boxes are not already separated before motion.
 */

export interface Box {
  /** Top-left corner. */
  x: number;
  y: number;
  w: number;
  h: number;
}

export interface Vec2 {
  x: number;
  y: number;
}

export interface SweepResult {
  /** True if the moving box hits the static box at some t in [0, 1]. */
  hit: boolean;
  /**
   * Time of impact in [0, 1]. Meaningful only when `hit` is true.
   * For an initially-overlapping start state this is 0.
   */
  toi: number;
  /**
   * Surface normal at the point of impact, pointing out of the wall,
   * i.e. opposite the direction of travel along the impact axis
   * (e.g. moving right into a wall gives normal (-1, 0)).
   * Zero vector only for the initial-overlap case with no clear axis.
   */
  normal: Vec2;
}

const EPS = 1e-12;

/** True if the two axis-aligned boxes overlap (inclusive of touching edges). */
export function overlaps(a: Box, b: Box): boolean {
  return (
    a.x < b.x + b.w && a.x + a.w > b.x &&
    a.y < b.y + b.h && a.y + a.h > b.y
  );
}

function makeResult(hit: boolean, toi = 0, normal: Vec2 = { x: 0, y: 0 }): SweepResult {
  return { hit, toi, normal };
}

/**
 * Sweep `moving` from its current position along `vel` (pixels per full
 * step) against static box `wall`. Returns time of impact in [0, 1] and
 * the hit normal, or `{ hit: false }`.
 *
 * If the boxes already overlap at t = 0, returns a hit with toi = 0 and a
 * depenetration normal along the axis of least penetration.
 */
export function sweepAABB(moving: Box, vel: Vec2, wall: Box): SweepResult {
  // Initial overlap: report immediate contact, depenetrate along least-penetration axis.
  if (overlaps(moving, wall)) {
    const overlapX = Math.min(moving.x + moving.w, wall.x + wall.w) - Math.max(moving.x, wall.x);
    const overlapY = Math.min(moving.y + moving.h, wall.y + wall.h) - Math.max(moving.y, wall.y);
    const cx = (moving.x + moving.w / 2) - (wall.x + wall.w / 2);
    const cy = (moving.y + moving.h / 2) - (wall.y + wall.h / 2);
    if (overlapX <= overlapY) {
      return makeResult(true, 0, { x: cx >= 0 ? 1 : -1, y: 0 });
    }
    return makeResult(true, 0, { x: 0, y: cy >= 0 ? 1 : -1 });
  }

  let tEnter = -Infinity; // earliest time all axes simultaneously overlap
  let tExit = +Infinity;  // latest time any axis still overlaps
  let enterAxis: 'x' | 'y' | null = null;
  let enterSign = 0;

  const processAxis = (
    pos: number, size: number, v: number,
    wallMin: number, wallMax: number,
    axis: 'x' | 'y',
  ): boolean => {
    if (Math.abs(v) < EPS) {
      // No relative motion on this axis: must already overlap this slab.
      if (pos + size <= wallMin || pos >= wallMax) return false;
      return true; // entry = -inf, exit = +inf contributions
    }
    // invV > 0: moving toward positive; entry via near face, exit via far face.
    const invV = 1 / v;
    let entry = (wallMin - (pos + size)) * invV; // leading edge reaches wallMin
    let exit = (wallMax - pos) * invV;           // trailing edge passes wallMax
    let sign = -1; // normal opposes velocity direction on entry axis
    if (entry > exit) {
      [entry, exit] = [exit, entry]; // moving away on this axis: entry is really the "far" crossing
      sign = 1;
    }
    if (entry > tEnter) {
      tEnter = entry;
      enterAxis = axis;
      enterSign = sign;
    }
    if (exit < tExit) tExit = exit;
    return true;
  };

  const xOk = processAxis(moving.x, moving.w, vel.x, wall.x, wall.x + wall.w, 'x');
  const yOk = processAxis(moving.y, moving.h, vel.y, wall.y, wall.y + wall.h, 'y');
  if (!xOk || !yOk) return makeResult(false);

  // Interval of contact must intersect [EPS, 1]. The EPS lower bound means
  // "moving apart" solutions (tEnter < 0 with tExit also behind us) are
  // rejected, while genuine grazing/touching within the step count as hits.
  if (!(enterAxis !== null)) return makeResult(false);
  if (tEnter > tExit || tEnter > 1 || tExit < 0 || tEnter < 0) {
    // tEnter < 0 with tExit >= 0 can't happen here because we already
    // handled initial overlap above; anything else outside [0,1] misses.
    return makeResult(false);
  }

  const normal: Vec2 =
    enterAxis === 'x'
      ? { x: enterSign * Math.sign(vel.x || 1) * (vel.x >= 0 ? 1 : -1), y: 0 }
      : { x: 0, y: vel.y >= 0 ? -1 : 1 };

  return makeResult(true, clamp01(tEnter), normal);
}

function clamp01(t: number): number {
  return Math.min(1, Math.max(0, t));
}

/**
 * Slide response: advance to the time of impact, remove the velocity
 * component along the hit normal, then continue with the remaining time.
 * Returns the resolved final position; guaranteed non-overlapping with the
 * wall (nudged out by SKIN along the normal to avoid float-touch issues).
 */
export function SLIDE_SKIN = 1e-6;

