   */
  normal: Vec2;
}

const EPS = 1e-12;

/** True if the two axis-aligned boxes overlap (strict interiors intersect). */
export function overlaps(a: Box, b: Box): boolean {
  return (
    a.x < b.x + b.w && a.x + a.w > b.x &&
    a.y < b.y + b.h && a.y + a.h > b.y
  );
}

function noHit(): SweepResult {
  return { hit: false, toi: 0, normal: { x: 0, y: 0 } };
}

