  if (overlaps(moving, wall)) {
    const overlapX =
      Math.min(moving.x + moving.w, wall.x + wall.w) - Math.max(moving.x, wall.x);
    const overlapY =
      Math.min(moving.y + moving.h, wall.y + wall.h) - Math.max(moving.y, wall.y);
    const cx = moving.x + moving.w / 2 - (wall.x + wall.w / 2);
    const cy = moving.y + moving.h / 2 - (wall.y + wall.h / 2);
    return overlapX <= overlapY
      ? { hit: true, toi: 0, normal: { x: cx >= 0 ? 1 : -1, y: 0 } }
      : { hit: true, toi: 0, normal: { x: 0, y: cy >= 0 ? 1 : -1 } };
  }

  let tEnter = -Infinity; // first instant all axes simultaneously overlap
  let tExit = +Infinity;  // last instant any axis still overlaps
  let enterAxisIsX = false;
  let enterNormal: Vec2 = { x: 0, y: 0 };

