    pos: number,
    size: number,
    v: number,
    wallMin: number,
    wallMax: number,
    isX: boolean,
  ): boolean => {
    if (Math.abs(v) < EPS) {
      // No motion on this axis: this slab must already contain the box.
      return pos + size > wallMin && pos < wallMax;
    }
    const invV = 1 / v;
    let entry = (wallMin - (pos + size)) * invV; // leading edge reaches wallMin
    let exit = (wallMax - pos) * invV;           // trailing edge passes wallMax
    // Normal opposes travel direction on the entry axis.
    let normal: Vec2;
