      normal = isX ? { x: -1, y: 0 } : { x: 0, y: -1 };
    } else {
      [entry, exit] = [exit, entry];
      normal = isX ? { x: 1, y: 0 } : { x: 0, y: 1 };
    }
    if (entry > tEnter) {
      tEnter = entry;
      enterAxisIsX = isX;
      enterNormal = normal;
    }
    if (exit < tExit) tExit = exit;
    return true;
  };

