  if (!slab(moving.y, moving.h, vel.y, wall.y, wall.y + wall.h, false)) return noHit();

  // Contact interval must lie fully within the step and actually be an interval.
  if (tExit < tEnter || tEnter > 1 || tExit < 0 || tEnter < 0) return noHit();

  return { hit: true, toi: tEnter, normal: enterNormal };
}

/** Small push-out distance so sliding results never graze the wall exactly. */
export const SKIN = 1e-6;

/**
 * Slide response: advance to the time of impact, remove the velocity
 * component along the hit normal, then continue with the remaining fraction
 * of the step. Returns the resolved final top-left position.
 */
export function slide(
  moving: Box,
  vel: Vec2,
  wall: Box,
): { x: number; y: number; result: SweepResult } {
  const result = sweepAABB(moving, vel, wall);
  if (!result.hit) {
    return { x: moving.x + vel.x, y: moving.y + vel.y, result };
  }

  // Advance to contact.
  let x = moving.x + vel.x * result.toi;
  let y = moving.y + vel.y * result.toi;

  // Push out of the wall along the normal...
  x += result.normal.x * SKIN;
  y += result.normal.y * SKIN;

  // ...and cancel motion into the surface for the rest of the step.
  const remaining = 1 - result.toi;
  const vx = vel.x - result.normal.x * (vel.x * result.normal.x + vel.y * result.normal.y);
  const vy = vel.y - result.normal.y * (vel.x * result.normal.x + vel.y * result.normal.y);
  x += vx * remaining;
  y += vy * remaining;

  return { x, y, result };
}

