const bullet: Box = { x: 0, y: 50, w: 4, h: 4 };
const wall: Box = { x: 100, y: 0, w: 2, h: 100 };
const fastVel: Vec2 = { x: 300, y: 0 }; // px per 1/60s step

describe('naive discrete overlap check', () => {
  it('misses a 4px bullet tunneling through a 2px wall in one frame', () => {
    // After the full step the bullet teleports from x:[0,4] to x:[300,304].
    const endPos: Box = { ...bullet, x: bullet.x + fastVel.x };
    expect(endPos.x).toBe(300);
    // Discrete check sees no overlap -> collision silently skipped.
    expect(overlaps(endPos, wall)).toBe(false);
  });
});

describe('sweepAABB', () => {
  it('catches the same tunneling shot as a hit', () => {
    const r = sweepAABB(bullet, fastVel, wall);
    expect(r.hit).toBe(true);
    expect(r.normal).toEqual({ x: -1, y: 0 }); // wall's left face
  });

  it('computes TOI exactly for a hand-computed head-on shot', () => {
    // Leading edge starts at x=4; wall face at x=100.
    // 4 + 300*t = 100  =>  t = 96/300 = 0.32
    const r = sweepAABB(bullet, fastVel, wall);
    expect(Math.abs(r.toi - 96 / 300)).toBeLessThan(EPS);
    // Cross-check geometrically: box placed at TOI touches the wall face.
    const touched: Box = {
      x: bullet.x + fastVel.x * r.toi,
      y: bullet.y,
      w: bullet.w,
      h: bullet.h,
    };
    expect(touched.x + touched.w).toBeCloseTo(wall.x, 9);
  });

  it('computes TOI for diagonal motion into a horizontal floor', () => {
    // Box top-left (10, -40), size 8x8, vel (0, 200). Floor top at y=0.
    // Trailing edge: bottom edge at y=-32; -32 + 200*t = 0 => t = 0.16
    const box: Box = { x: 10, y: -40, w: 8, h: 8 };
    const r = sweepAABB(box, { x: 0, y: 200 }, { x: 0, y: 0, w: 500, h: 20 });
    expect(r.hit).toBe(true);
    expect(Math.abs(r.toi - 0.16)).toBeLessThan(EPS);
    expect(r.normal).toEqual({ x: 0, y: -1 });
  });

  it('reports no hit when moving away from the wall', () => {
    const behind: Box = { x: 110, y: 50, w: 4, h: 4 };
    expect(sweepAABB(behind, fastVel, wall).hit).toBe(false);
  });

  it('reports no hit when motion passes wide of the wall', () => {
    const offY: Box = { x: 0, y: 200, w: 4, h: 4 };
    expect(sweepAABB(offY, fastVel, wall).hit).toBe(false);
  });

  it('reports no hit when the target is beyond one step of travel', () => {
    const farWall: Box = { x: 400, y: 0, w: 2, h: 100 };
    expect(sweepAABB(bullet, fastVel, farWall).hit).toBe(false);
  });

  it('handles a stationary axis via slab containment', () => {
    // No vertical motion, but vertical slabs do overlap -> still a hit.
    expect(sweepAABB(bullet, { x: 300, y: 0 }, wall).hit).toBe(true);
    // No vertical motion AND vertically separated -> miss despite x sweep.
    const highBullet: Box = { ...bullet, y: 150 };
    expect(sweepAABB(highBullet, { x: 300, y: 0 }, wall).hit).toBe(false);
  });

  it('reports immediate hit for initial overlap', () => {
    const inside: Box = { x: 101, y: 50, w: 4, h: 4 };
    const r = sweepAABB(inside, { x: 10, y: 0 }, wall);
    expect(r.hit).toBe(true);
    expect(r.toi).toBe(0);
    expect(r.normal).toEqual({ x: -1, y: 0 }); // depenetrate leftward (least-pen axis)
  });

  it('still detects ultra-thin walls at extreme speed', () => {
    const razor: Box = { x: 250, y: 0, w: 0.001, h: 100 }; // microns-thick wall
    const r = sweepAABB({ x: 0, y: 50, w: 4, h: 4 }, { x: 600, y: 0 }, razor);
    expect(r.hit).toBe(true);
    expect(Math.abs(r.toi - 246 / 600)).toBeLessThan(EPS);
  });
});

describe('sliding response', () => {
  it('keeps the resolved box outside the wall while preserving tangent motion', () => {
    // Diagonal shot into the wall's left face; should land flush and slide up.
    const slider: Box = { x: 0, y: 90, w: 8, h: 8 };
    const vel: Vec2 = { x: 300, y: -150 };
    const out = slide(slider, vel, wall);

    expect(out.result.hit).toBe(true);
    // Hand-computed TOI: 8 + 300*t = 100 => t = 92/300
    expect(out.result.toi).toBeCloseTo(92 / 300, 6);
    expect(out.result.normal).toEqual({ x: -1, y: 0 });

    // Final box must not intersect the wall...
    const finalBox: Box = { x: out.x, y: out.y, w: slider.w, h: slider.h };
    expect(overlaps(finalBox, wall)).toBe(false);
    // ...must sit flush against the wall's left face...
    expect(finalBox.x + finalBox.w).toBeGreaterThanOrEqual(wall.x); // SKIN keeps us just outside
    expect(finalBox.x + finalBox.w).toBeLessThan(wall.x + 0.001);
    // ...and must have kept its tangential (y) motion: full-step y would be 90-150=-60.
    expect(out.y).toBeCloseTo(-60, 6);
  });

  it('unobstructed slide falls through to plain integration', () => {
    const free: Box = { x: 0, y: 0, w: 8, h: 8 };
    const out = slide(free, { x: 12, y: 34 }, { x: 1000, y: 0, w: 2, h: 2 });
    expect(out.result.hit).toBe(false);
    expect(out.x).toBe(12);
    expect(out.y).toBe(34);
  });

  it('never ends up inside the wall across randomized shots', () => {
    // Deterministic pseudo-random spread of start positions/velocities.
    let seed = 12345;
    const rand = () => {
      seed = (seed * 1103515245 + 12345) % 2147483648;
      return seed / 2147483648;
    };
    for (let i = 0; i < 500; i++) {
      const box: Box = {
        x: rand() * 160 - 30,
        y: rand() * 160 - 30,
        w: 2 + rand() * 10,
        h: 2 + rand() * 10,
      };
      const vel: Vec2 = { x: rand() * 600 - 300, y: rand() * 600 - 300 };
      const out = slide(box, vel, wall);
      const finalBox: Box = { x: out.x, y: out.y, w: box.w, h: box.h };
      if (out.result.hit && out.result.toi === 0) continue; // depenetration case documented separately
      // Any resolved state that started clear must remain clear.
      if (!overlaps(box, wall)) {
        expect(overlaps(finalBox, wall), `case ${i}: ${JSON.stringify(finalBox)}`).toBe(false);
      }
    }
  });
});

